<script setup lang="ts">
const anchor=ref(new Date().toLocaleDateString('sv-SE')),view=ref('week'),selected=ref(anchor.value),planning=ref(false)
const iso=(d:Date)=>d.toISOString().slice(0,10)
const range=computed(()=>{const d=new Date(anchor.value+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-(d.getUTCDay()+6)%7);const last=new Date(d);last.setUTCDate(last.getUTCDate()+(view.value==='month'?41:6));return {start:iso(d),end:iso(last)}})
const {data:c,error,refresh}=await useFetch<any>('/api/platform/training',{query:range})
const current=computed(()=>c.value?.days.find((d:any)=>d.date===selected.value))
const move=(step:number)=>{const d=new Date(anchor.value+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+step*(view.value==='month'?28:7));anchor.value=iso(d)}
const fmt=(v:any)=>v==null?'—':Number(v).toLocaleString('it-IT',{maximumFractionDigits:0})
const labels:any={completed:'Eseguito e collegato',candidate:'Da collegare',ambiguous:'Più sedute: scegli il collegamento',unmatched:'Senza collegamento',upcoming:'Pianificato',planned:'Pianificato',cancelled:'Annullato'}
const pending=ref<any>(null),message=ref(''),busy=ref(false),newDates=ref<Record<string,string>>({})
async function change(body:any,confirm=false){busy.value=true;message.value='';try{const value=await $fetch<any>('/api/platform/memory',{method:'POST',headers:{'x-csrf-token':c.value.csrf},body:confirm?{kind:pending.value.kind,confirm:true,preview_token:pending.value.preview_token}:body});if(confirm){pending.value=null;message.value='Modifica salvata.';await refresh()}else pending.value={...value,kind:body.kind}}catch(e:any){message.value=e.data?.error||'Modifica non salvata'}finally{busy.value=false}}
function openCard(day:any,card:any){selected.value=day.date;if(card.source==='completed')navigateTo('/activity/'+card.activity_id)}
</script>
<template><div class="space-y-6 w-full min-w-0 max-w-[1800px] mx-auto pb-10"><div class="flex flex-wrap gap-3 justify-between"><div><p class="eyebrow">PROGRAMMA, ESECUZIONE E RECUPERO</p><h1 class="text-3xl font-bold mt-2">Il tuo calendario.</h1><p class="muted mt-2">Piani e attività Garmin distinti; collegamenti confermati, sensazioni e contesto del giorno.</p></div><UButton @click="planning=!planning" icon="i-lucide-calendar-plus">{{planning?'Chiudi programmazione':'Programma un blocco'}}</UButton></div><UAlert v-if="error" color="error" title="Calendario temporaneamente non disponibile"/><template v-if="c"><PlanningPanel v-if="planning" :settings="c.settings" :csrf="c.csrf" @saved="refresh"/><div class="flex flex-wrap gap-2 items-center"><UButton @click="move(-1)" aria-label="Periodo precedente" icon="i-lucide-chevron-left" variant="outline"/><input type="date" v-model="anchor" aria-label="Data calendario"/><UButton @click="move(1)" aria-label="Periodo successivo" icon="i-lucide-chevron-right" variant="outline"/><UButton @click="anchor=new Date().toLocaleDateString('sv-SE')" variant="outline">Oggi</UButton><select v-model="view" aria-label="Vista calendario"><option value="week">Settimana</option><option value="month">Sei settimane</option></select><p class="muted">Verde: registrato · ambra: piano · blu: piano collegato</p></div><div v-for="week in c.weeks" class="panel space-y-4"><div class="flex flex-wrap justify-between gap-3"><h2 class="font-semibold">{{week.start}} → {{week.end}}</h2><p class="muted">{{week.completed_n}} sedute · {{fmt(week.distance_m)}} m ({{week.distance_n}} con distanza) · {{week.planned_n}} piani / {{fmt(week.planned_m)}} m · carico Garmin {{fmt(week.load)}} ({{week.load_n}}/{{week.completed_n}} sedute)</p></div><div class="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-7 gap-2"><div v-for="day in week.days" :key="day.date" :class="{'ring-1 ring-green-600 rounded-2xl':selected===day.date}"><CoachCalendarDayCard :date="new Date(day.date+'T12:00:00Z')" :activities="day.cards" :day-summary="{plannedCount:day.planned_n,completedCount:day.completed_n}" :is-today="day.date===new Date().toLocaleDateString('sv-SE')" compact @day-click="selected=day.date" @activity-click="openCard(day,$event)"/><button class="text-[11px] text-zinc-400 p-2 text-left w-full" @click="selected=day.date">HRV {{day.hrv_ms??'—'}} · sonno {{day.sleep_hours==null?'—':day.sleep_hours.toLocaleString('it-IT',{maximumFractionDigits:1})}} h <span v-if="day.wellness">· feedback presente</span></button></div></div></div><div v-if="current" class="grid lg:grid-cols-2 gap-5"><div class="panel space-y-4"><h2 class="text-xl font-semibold">Giornata del {{current.date}}</h2><p class="muted">{{c.match_note}}</p><p v-if="!current.plans.length" class="muted">Nessun piano salvato per questa giornata.</p><div v-for="p in current.plans" class="border border-zinc-800 rounded-xl p-4 space-y-3"><h3 class="font-semibold">{{p.title}} · {{fmt(p.total_m)}} m</h3><UBadge :color="p.match_status==='completed'?'primary':'neutral'">{{labels[p.match_status]}}</UBadge><p v-for="b in p.blocks" class="text-sm">{{b.label}} · {{b.reps}} × {{b.distance_m}} m · {{b.zone}} · recupero {{b.rest_s}}s</p><p v-if="p.actual" class="muted">Eseguito {{fmt(p.actual.distance_m)}} m · differenza dal piano {{fmt(p.delta_m)}} m</p><template v-if="p.match_status!=='cancelled'"><div v-for="a in p.candidates" class="flex flex-wrap gap-2 items-center"><NuxtLink :to="'/activity/'+a.activity_id" class="text-green-400 text-sm">{{a.name}} · {{fmt(a.distance_m)}} m</NuxtLink><UButton v-if="p.actual?.activity_id!==a.activity_id" size="xs" variant="outline" @click="change({kind:'plan-links',plan_id:p.id,activity_id:a.activity_id})">Anteprima collegamento</UButton></div><div class="flex flex-wrap gap-2"><input type="date" v-model="newDates[p.id]" aria-label="Nuova data piano"/><UButton size="xs" variant="outline" @click="change({kind:'plan-revisions',plan_id:p.id,status:'planned',date:newDates[p.id]})" :disabled="!newDates[p.id]">Sposta: anteprima</UButton><UButton size="xs" color="neutral" variant="outline" @click="change({kind:'plan-revisions',plan_id:p.id,status:'cancelled'})">Annulla: anteprima</UButton></div></template></div><NuxtLink v-for="a in current.activities" :to="'/activity/'+a.activity_id" class="block text-green-400 text-sm">{{a.name}} · {{fmt(a.distance_m)}} m → dettaglio</NuxtLink><p v-if="!current.activities.length" class="muted">Nessuna attività registrata. Il riposo non viene dedotto dall’assenza di registrazioni.</p><NuxtLink :to="'/recovery'" class="block text-green-400">Apri monitoraggio e tendenze →</NuxtLink></div><div class="panel"><WellnessForm :date="current.date" :csrf="c.csrf" @saved="refresh"/></div></div><div v-if="pending" class="panel border-green-800"><h2 class="font-semibold">Conferma la modifica proposta</h2><p class="muted mt-3">{{pending.preview.title}} · piano {{pending.preview.plan_id}} · {{pending.preview.date||''}} {{pending.preview.status||''}}</p><p v-if="pending.preview.activity_id" class="muted mt-2">Attività Garmin #{{pending.preview.activity_id}}</p><UButton class="mt-4" @click="change({},true)" :loading="busy">Conferma modifica</UButton></div><p role="status" class="text-amber-300 text-sm">{{message}}</p></template></div></template>
